def render_stream():
    name=st.session_state.get("selected_stream")
    render_back("journey","back_stream")
    if not name or name not in INTERMEDIATE:
        st.error("No intermediate stream is selected. Please choose a stream again.")
        if st.button("🚀 Back to Journey", key="missing_stream_back", use_container_width=True):
            back("journey")
        return
    d=INTERMEDIATE[name]
    st.markdown(f'<div class="fp-title">{d["icon"]} {name} Stream</div>',unsafe_allow_html=True)
    st.markdown('<div class="fp-sub">First see the subjects, then open a course to continue into its branches, skills, projects, internships, jobs and higher studies.</div>',unsafe_allow_html=True)

    st.markdown('<div class="fp-section">📚 What you study</div>',unsafe_allow_html=True)
    cols=st.columns(3)
    for i,s in enumerate(d["subjects"]):
        with cols[i%3]:
            st.markdown(f'<div class="fp-card"><h3>{s}</h3><p>Core subject in the {name} pathway.</p></div>',unsafe_allow_html=True)

    st.markdown('<div class="fp-section">🎓 Click a course / next degree</div>',unsafe_allow_html=True)
    cols=st.columns(2)
    for i,c in enumerate(d["courses"]):
        with cols[i%2]:
            is_eng=(c=="B.Tech / B.E.")
            desc="Explore all engineering branches" if is_eng else "Open subjects, specializations, skills, projects, internships, jobs and higher studies"
            st.markdown(f'<div class="fp-card"><div class="fp-chip">{ "🎓 Engineering" if is_eng else "📘 Degree / Course" }</div><h3>{c}</h3><p>{desc}</p></div>',unsafe_allow_html=True)
            if st.button("Explore this course →",key="course_"+str(i),use_container_width=True): select_course(c)

    st.markdown('<div class="fp-section">🌳 Stream graduation tree</div>',unsafe_allow_html=True)
    st.markdown(f'<div class="fp-tree"><div class="fp-tree-line">Class 10</div><div class="fp-tree-line">↓ {name}</div><div class="fp-tree-line">↓ Degree / Course</div><div class="fp-tree-line">↓ Specialization / Branch</div><div class="fp-tree-line">↓ Skills → Projects → Internship</div><div class="fp-tree-line">↓ Job / Higher Studies</div></div>',unsafe_allow_html=True)

