def render_course_detail():
    name=st.session_state.get("selected_course")
    render_back("stream","back_course_detail")
    if not name:
        st.error("No course is selected. Please go back and choose a course.")
        if st.button("📚 Back to Courses", key="missing_course_back", use_container_width=True):
            back("stream")
        return
    name=str(name).strip()
    if not name:
        st.error("The selected course name is empty. Please choose a course again.")
        if st.button("📚 Back to Courses", key="empty_course_back", use_container_width=True):
            back("stream")
        return
    profile=course_profile(name)
    parent=st.session_state.get("selected_stream") or "After Class 10"
    st.markdown(f'<div class="fp-title">📘 {name}</div>',unsafe_allow_html=True)
    st.markdown(f'<div class="fp-sub">{profile["description"]}</div>',unsafe_allow_html=True)
    st.markdown(f'<div class="fp-note"><b>Path:</b> Class 10 → {parent} → {name} → Specialization / Branch → Skills → Projects → Internship → Job / Higher Studies</div>',unsafe_allow_html=True)

    st.markdown('<div class="fp-section">🌿 Branches / Specializations</div>',unsafe_allow_html=True)
    cols=st.columns(3)
    for i,b in enumerate(profile["branches"]):
        with cols[i%3]:
            st.markdown(f'<div class="fp-card"><h3>🔹 {b}</h3><p>Explore the subject area and practical pathway for this specialization.</p></div>',unsafe_allow_html=True)
            if st.button("View branch details →",key="spec_"+str(i),use_container_width=True):
                st.session_state.selected_specialization=b
                st.rerun()

    spec=st.session_state.get("selected_specialization")
    if spec:
        st.markdown(f'<div class="fp-section">🔍 {spec}</div>',unsafe_allow_html=True)
        st.info(f"This specialization belongs to {name}. Exact paper names and semester structure vary by university; use the specialization as a guide and verify the institution curriculum.")

    st.markdown('<div class="fp-section">📚 Subjects</div>',unsafe_allow_html=True)
    cols=st.columns(3)
    for i,x in enumerate(profile["subjects"]):
        with cols[i%3]: st.markdown(f'<div class="fp-card"><h3>{x}</h3></div>',unsafe_allow_html=True)

    for title,key,icon in [(T["skills"],"skills","🧠"),(T["projects"],"projects","🛠️"),(T["intern"],"internships","💼"),(T["careers"],"careers","🚀")]:
        st.markdown(f'<div class="fp-section">{icon} {title}</div>',unsafe_allow_html=True)
        cols=st.columns(3)
        for i,x in enumerate(profile[key]):
            with cols[i%3]: st.markdown(f'<div class="fp-card"><h3>{x}</h3></div>',unsafe_allow_html=True)

    st.markdown(f'<div class="fp-section">🌳 {T["tree"]}</div>',unsafe_allow_html=True)
    st.markdown(f'<div class="fp-tree"><div class="fp-tree-line">Class 10 → {parent}</div><div class="fp-tree-line">↓ {name}</div><div class="fp-tree-line">↓ {spec or "Choose a branch / specialization"}</div><div class="fp-tree-line">↓ Skills → Projects → Internship</div><div class="fp-tree-line">↓ Career / Higher Study</div></div>',unsafe_allow_html=True)

    st.markdown('<div class="fp-section">🎓 Higher Studies</div>',unsafe_allow_html=True)
    for x in profile["higher"]: st.write("•",x)

